"""v13 docs: README.md, COMPONENTS.md, UNITY_CONTRACT.md of export/unity_v13/Assets/UtilityPlane (copied from v12r2 by
make_package_v13.py) patched for v13: light fixtures, lens texture, sliding cargo doors. Run after make_package_v13.py.
python3 build_docs13.py"""
import os, json, re

PKG = '/home/claude/plane/export/unity_v13/Assets/UtilityPlane'
SOCK = json.load(open(os.path.join(PKG, 'Data', 'sockets.json')))
DJ = json.load(open(os.path.join(PKG, 'Data', 'doors.json')))


def patch(name, pairs):
    p = os.path.join(PKG, name)
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        n = s.count(a)
        assert n == 1, (name, n, a[:120])
        s = s.replace(a, b)
    open(p, 'w', encoding='utf-8').write(s)
    print(name, 'patched', len(pairs))


def f3(v):
    return ', '.join(f'{x:.3f}' for x in v)


